import { formatRiskMoment } from '../../core/risk-copy.e5eb2355d50d.mjs'; import { sha256 } from '../../core/receipt.d519c8b66de5.mjs';
export function createApprovalCard(input={}){const risk=formatRiskMoment({...input,kind:input.kind??'approval'});const allowed=new Set(['approve','deny','request-change']);return Object.freeze({risk,decide(decision){if(!allowed.has(decision))throw new Error('Unknown approval decision');const base={schema:'nolane.ui.approval-decision.v1',id:String(input.id),decision,scope:risk.scope};return Object.freeze({...base,receiptSha256:sha256(JSON.stringify(base))})}})}
